@Override
    public void close() throws IOException {
        if (finished) {
            return;
        }

        // Close the output stream
        IOException exc;
        try {
            content.close();
        } catch (final IOException ioe) {
            exc = ioe;
        }

        // Notify of end of output
        exc = null;
        try {
            onClose();
        } catch (final IOException ioe) {
            exc = ioe;
        }

        finished = true;

        if (exc != null) {
            throw exc;
        }
    }

