@Override
    public void close() throws IOException {
        if (closed) {
            return;
        }
        // Notify on close that there was an IOException while writing
        if (exception != null) {
            throw exception;
        }
        try {
            this.closed = true;
            // Close the
            this.file.endOutput();
        } catch (final Exception e) {
            throw new FileSystemException(e);
        }
    }

