@Override
    public void writeChar(final int v) throws IOException {
        buffer2[0] = (byte) ((v >>> 8) & BYTE_VALUE_MASK);
        buffer2[1] = (byte) ((v >>> 0) & BYTE_VALUE_MASK);
        write(buffer2);
    }

@Override
    public void writeChars(final String s) throws IOException {
        final int len = s.length();
        for (int i = 0; i < len; i++) {
